import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { layer as sqliteLayer } from "@zuse/sqlite";
import { Effect, Layer, ManagedRuntime } from "effect";
import { SqlClient } from "effect/unstable/sql";
import { describe, expect, it } from "vitest";
import {
	MigrationsLive,
	MigrationsThrough0045Live,
} from "../../src/persistence/migrations.ts";

const migratedRuntime = (
	filename: string,
	migrations: typeof MigrationsLive,
) => {
	const sqlite = sqliteLayer({ filename, disableWAL: true });
	return ManagedRuntime.make(
		Layer.merge(sqlite, migrations.pipe(Layer.provide(sqlite))),
	);
};

describe("migration 0045 upgrade compatibility", () => {
	it("preserves projects, chats, and sessions and accepts a new chat", async () => {
		let stage = "initialize migration-0045 database";
		const directory = mkdtempSync(join(tmpdir(), "zuse-migration-0045-"));
		const filename = join(directory, "zuse.sqlite");
		const legacyRuntime = migratedRuntime(filename, MigrationsThrough0045Live);

		try {
			stage = "insert migration-0045 rows";
			await legacyRuntime.runPromise(
				Effect.gen(function* () {
					const sql = yield* SqlClient.SqlClient;
					const createdAt = "2026-01-01T00:00:00.000Z";
					stage = "insert the legacy project";
					yield* sql`
						INSERT INTO projects (id, path, name, created_at, updated_at)
						VALUES ('project-legacy', '/tmp/project-legacy', 'Legacy project',
							${createdAt}, ${createdAt})
					`;
					stage = "insert the legacy chat";
					yield* sql`
						INSERT INTO chats
							(id, project_id, worktree_id, title, active_session_id,
							 origin_session_id, archived_at, archived_worktree_json,
							 last_message_at, last_read_at, created_at, updated_at)
						VALUES ('chat-legacy', 'project-legacy', NULL, 'Legacy chat',
							NULL, NULL, NULL, NULL, ${createdAt}, ${createdAt},
							${createdAt}, ${createdAt})
					`;
					stage = "insert the legacy session";
					yield* sql`
						INSERT INTO sessions
							(id, project_id, title, provider_id, model, status, chat_id,
							 created_at, updated_at)
						VALUES ('session-legacy', 'project-legacy', 'Legacy chat', 'codex',
							'gpt-5', 'idle', 'chat-legacy', ${createdAt}, ${createdAt})
					`;
					stage = "link the legacy chat session";
					yield* sql`
						UPDATE chats SET active_session_id = 'session-legacy'
						WHERE id = 'chat-legacy'
					`;
				}),
			);
			await legacyRuntime.dispose();

			stage = "run current migrations";
			const currentRuntime = migratedRuntime(filename, MigrationsLive);
			try {
				stage = "verify upgraded rows";
				const result = await currentRuntime.runPromise(
					Effect.gen(function* () {
						const sql = yield* SqlClient.SqlClient;
						const integrity = yield* sql<{ readonly quick_check: string }>`
							PRAGMA quick_check
						`;
						const counts = yield* sql<{
							readonly projects: number;
							readonly chats: number;
							readonly sessions: number;
						}>`
							SELECT
								(SELECT COUNT(*) FROM projects) AS projects,
								(SELECT COUNT(*) FROM chats) AS chats,
								(SELECT COUNT(*) FROM sessions) AS sessions
						`;
						const createdAt = "2026-01-02T00:00:00.000Z";
						yield* sql`
							INSERT INTO chats
								(id, project_id, worktree_id, title, active_session_id,
								 origin_session_id, archived_at, archived_worktree_json,
								 last_message_at, last_read_at, created_at, updated_at)
							VALUES ('chat-new', 'project-legacy', NULL, 'New chat', NULL,
								NULL, NULL, NULL, NULL, ${createdAt}, ${createdAt}, ${createdAt})
						`;
						const newChats = yield* sql<{ readonly count: number }>`
							SELECT COUNT(*) AS count FROM chats WHERE id = 'chat-new'
						`;
						return { integrity, counts, newChats };
					}),
				);

				expect(result.integrity).toEqual([{ quick_check: "ok" }]);
				expect(result.counts).toEqual([{ projects: 1, chats: 1, sessions: 1 }]);
				expect(result.newChats).toEqual([{ count: 1 }]);
			} finally {
				await currentRuntime.dispose();
			}
		} catch (cause) {
			throw new Error(`Upgrade test failed while attempting to ${stage}.`, {
				cause,
			});
		} finally {
			await legacyRuntime.dispose();
			rmSync(directory, { recursive: true, force: true });
		}
	});
});
import { Effect } from "effect";
import { SqlClient } from "effect/unstable/sql";

/**
 * Repairs operations written by a pre-durable-lifecycle runtime after
 * migration 0050 had already added the new columns. Those writers only set
 * the legacy `status`, leaving `phase` at its default (`persisted`). The new
 * renderer then mistakes completed chats for interrupted creation work.
 */
export const Migration0051LegacyChatCreationPhaseRepair = Effect.gen(
	function* () {
		const sql = yield* SqlClient.SqlClient;
		yield* sql`
			UPDATE chat_creation_operations
			SET phase = CASE status
				WHEN 'pending' THEN 'persisted'
				WHEN 'creating_workspace' THEN 'creating_workspace'
				WHEN 'creating_chat' THEN 'starting_agent'
				WHEN 'succeeded' THEN 'running'
				ELSE 'failed'
			END,
			failure_stage = CASE WHEN status = 'failed' THEN 'legacy_unknown' ELSE NULL END,
			retryable = CASE WHEN status = 'failed' THEN 0 ELSE 1 END,
			phase_started_at = COALESCE(phase_started_at, updated_at)
			WHERE request_fingerprint IS NULL
			  AND phase != CASE status
				WHEN 'pending' THEN 'persisted'
				WHEN 'creating_workspace' THEN 'creating_workspace'
				WHEN 'creating_chat' THEN 'starting_agent'
				WHEN 'succeeded' THEN 'running'
				ELSE 'failed'
			  END
		`;
	},
);
import { SqlClient } from "effect/unstable/sql";
import { Effect } from "effect";

/**
 * Worktrees + per-repository settings.
 *
 *  - `worktrees` rows track each `git worktree` memoize owns for a project.
 *    Removed from disk via `WorktreeService.remove`; cascades from the
 *    parent project so deleting a project drops the rows too (the disk
 *    removal step happens before the DB delete in the service so we never
 *    leak orphan checkouts).
 *  - `sessions.worktree_id` points at the worktree the session runs in.
 *    NULL means the session uses the project's main checkout. Set to NULL
 *    when the worktree row is removed so the session falls back to the
 *    main checkout instead of pointing at a missing row.
 *  - `repository_settings` carries per-repo overrides. Every override is
 *    nullable so the renderer can fall through to the global default.
 */
export const Migration0008WorktreesAndRepoSettings = Effect.gen(function* () {
  const sql = yield* SqlClient.SqlClient;

  yield* sql`
    CREATE TABLE worktrees (
      id TEXT PRIMARY KEY,
      project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
      path TEXT NOT NULL,
      name TEXT NOT NULL,
      branch TEXT NOT NULL,
      base_branch TEXT NOT NULL,
      created_at TEXT NOT NULL,
      UNIQUE(project_id, path)
    )
  `;

  yield* sql`
    CREATE INDEX idx_worktrees_project
      ON worktrees(project_id, created_at DESC)
  `;

  yield* sql`
    ALTER TABLE sessions
      ADD COLUMN worktree_id TEXT REFERENCES worktrees(id) ON DELETE SET NULL
  `;

  yield* sql`
    CREATE TABLE repository_settings (
      project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,
      default_provider_id TEXT,
      default_model TEXT,
      default_runtime_mode TEXT,
      auto_create_worktree INTEGER NOT NULL DEFAULT 0,
      worktree_base_dir TEXT
    )
  `;
});

