+import { type DragEvent, useMemo, useRef, useState } from "react";
+import { useSidebarProjectLayoutStore } from "../store/sidebar-project-layout.ts";
+import {
+	materializeSidebarLayout,
+	projectGroupIdFor,
+	type SidebarDragSource,
+	type SidebarDropTarget,
+	type SidebarLayoutNode,
+	sidebarGroupItemKey,
+} from "./sidebar-project-layout.ts";
+
+export type SidebarDropLine = "before" | "after" | "into";
+
+export type SidebarGroupDialog =
+	| { readonly kind: "create"; readonly projectKeys: ReadonlyArray<string> }
+	| {
+			readonly kind: "rename";
+			readonly groupId: string;
+			readonly name: string;
+	  };
+
+const itemKeyOf = (node: SidebarLayoutNode): string =>
+	node.kind === "group" ? sidebarGroupItemKey(node.group.id) : node.key;
+
+export const useSidebarOrganize = (projectKeys: ReadonlyArray<string>) => {
+	const layout = useSidebarProjectLayoutStore((s) => s.layout);
+	const move = useSidebarProjectLayoutStore((s) => s.move);
+	const createGroup = useSidebarProjectLayoutStore((s) => s.createGroup);
+	const renameGroup = useSidebarProjectLayoutStore((s) => s.renameGroup);
+	const setGroupCollapsed = useSidebarProjectLayoutStore(
+		(s) => s.setGroupCollapsed,
+	);
+	const dissolveGroup = useSidebarProjectLayoutStore((s) => s.dissolveGroup);
+	const setGroupIconColor = useSidebarProjectLayoutStore(
+		(s) => s.setGroupIconColor,
+	);
+
+	const nodes = useMemo(
+		() => materializeSidebarLayout(projectKeys, layout),
+		[layout, projectKeys],
+	);
+
+	const dragSourceRef = useRef<SidebarDragSource | null>(null);
+	const skipClickRef = useRef(false);
+	const [drop, setDrop] = useState<{
+		readonly key: string;
+		readonly line: SidebarDropLine;
+	} | null>(null);
+	const [groupDialog, setGroupDialog] = useState<SidebarGroupDialog | null>(
+		null,
+	);
+
+	const topAfter = (index: number): SidebarDropTarget => {
+		const next = nodes[index + 1];
+		return next === undefined
+			? { kind: "end" }
+			: { kind: "before", itemKey: itemKeyOf(next) };
+	};
+
+	const clearDrag = (): void => {
+		dragSourceRef.current = null;
+		setDrop(null);
+	};
+
+	const applyDrop = (target: SidebarDropTarget): void => {
+		const source = dragSourceRef.current;
+		if (source === null) return;
+		move(source, target, projectKeys);
+		skipClickRef.current = true;
+		clearDrag();
+	};
+
+	const consumeSkipClick = (): boolean => {
+		if (!skipClickRef.current) return false;
+		skipClickRef.current = false;
+		return true;
+	};
+
+	const projectDragProps = (key: string, groupId: string | null) => {
+		const nodeIndex = nodes.findIndex((node) =>
+			node.kind === "project"
+				? node.key === key
+				: node.group.projectKeys.includes(key),
+		);
+		const node = nodes[nodeIndex];
+		const innerIndex =
+			node?.kind === "group" ? node.group.projectKeys.indexOf(key) : -1;
+		const nextInGroup =
+			node?.kind === "group"
+				? node.group.projectKeys[innerIndex + 1]
+				: undefined;
+		const before: SidebarDropTarget =
+			groupId === null
+				? { kind: "before", itemKey: key }
+				: { kind: "group-before", groupId, projectKey: key };
+		const after: SidebarDropTarget =
+			groupId === null
+				? nodeIndex >= 0
+					? topAfter(nodeIndex)
+					: { kind: "end" }
+				: nextInGroup === undefined
+					? { kind: "group-end", groupId }
+					: {
+							kind: "group-before",
+							groupId,
+							projectKey: nextInGroup,
+						};
+
+		return {
+			draggable: true,
+			onDragStart: (event: DragEvent<HTMLElement>) => {
+				dragSourceRef.current = { kind: "project", key };
+				event.dataTransfer.effectAllowed = "move";
+				event.dataTransfer.setData("text/plain", key);
+			},
+			onDragOver: (event: DragEvent<HTMLElement>) => {
+				if (dragSourceRef.current === null) return;
+				event.preventDefault();
+				event.stopPropagation();
+				event.dataTransfer.dropEffect = "move";
+				const rect = event.currentTarget.getBoundingClientRect();
+				const line: SidebarDropLine =
+					event.clientY < rect.top + rect.height / 2 ? "before" : "after";
+				setDrop((current) =>
+					current?.key === key && current.line === line
+						? current
+						: { key, line },
+				);
+			},
+			onDrop: (event: DragEvent<HTMLElement>) => {
+				event.preventDefault();
+				event.stopPropagation();
+				const rect = event.currentTarget.getBoundingClientRect();
+				applyDrop(event.clientY < rect.top + rect.height / 2 ? before : after);","path":"apps/renderer/src/lib/use-sidebar-organize.ts","commit_id":"87980a2129946d920e3d9ca1911a1fc0e4dc7162","original_commit_id":"a2eef6557a3fbb558bb740397c2ab140f28daeda","user":{"login":"notnotrachit","id":70265590,"node_id":"MDQ6VXNlcjcwMjY1NTkw","avatar_url":"https://avatars.githubusercontent.com/u/70265590?v=4","gravatar_id":"","url":"https://api.github.com/users/notnotrachit","html_url":"https://github.com/notnotrachit","followers_url":"https://api.github.com/users/notnotrachit/followers","following_url":"https://api.github.com/users/notnotrachit/following{/other_user}","gists_url":"https://api.github.com/users/notnotrachit/gists{/gist_id}","starred_url":"https://api.github.com/users/notnotrachit/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/notnotrachit/subscriptions","organizations_url":"https://api.github.com/users/notnotrachit/orgs","repos_url":"https://api.github.com/users/notnotrachit/repos","events_url":"https://api.github.com/users/notnotrachit/events{/privacy}","received_events_url":"https://api.github.com/users/notnotrachit/received_events","type":"User","user_view_type":"public","site_admin":false},"body":"Addressed in 87980a21. Nested project rows now reject group drag sources before calling preventDefault or setting an insertion indicator, while top-level project rows still accept group reordering. Added pure target-acceptance coverage for both cases.","created_at":"2026-08-26T13:20:10Z","updated_at":"2026-08-26T13:20:10Z","html_url":"https://github.com/swarajbachu/zuse/pull/522#discussion_r3863121387","pull_request_url":"https://api.github.com/repos/swarajbachu/zuse/pulls/522","_links":{"self":{"href":"https://api.github.com/repos/swarajbachu/zuse/pulls/comments/3863121387"},"html":{"href":"https://github.com/swarajbachu/zuse/pull/522#discussion_r3863121387"},"pull_request":{"href":"https://api.github.com/repos/swarajbachu/zuse/pulls/522"}}