		<AppAtomProvider>
			<GestureHandlerRootView
				style={{ flex: 1 }}
				onTouchStart={noteMobileInteraction}
			>
				<KeyboardProvider statusBarTranslucent>
					<ConnectivityRuntimeBridge />
					<ThemeProvider value={isDark ? DarkTheme : DefaultTheme}>
