type SheetDetent = number | "fitToContents";

/**
 * Native form sheets are an iOS presentation. On Android, react-native-screens
 * currently routes their inset handling through a bottom-sheet fragment that
 * can crash while the screen is attaching, so use the platform modal instead.
 */
export const adaptiveSheetPresentation = (
	platform: string,
	detents: readonly SheetDetent[],
) =>
	platform === "ios"
		? {
				presentation: "formSheet" as const,
				sheetAllowedDetents: [...detents],
				sheetInitialDetentIndex: 0,
				sheetGrabberVisible: true,
			}
		: { presentation: "modal" as const };

import { describe, expect, test } from "vitest";

import { adaptiveSheetPresentation } from "../../../src/lib/navigation-presentation";

