			sheetAllowedDetents: [0.7, 0.92],
			sheetInitialDetentIndex: 0,
			sheetGrabberVisible: true,
		});
	});

	test("uses a safe native modal without sheet options on Android", () => {
		expect(adaptiveSheetPresentation("android", [0.7, 0.92])).toEqual({
			presentation: "modal",
		});
	});
});

