import { Atom } from "effect/unstable/reactivity";

import {
	currentAccount,
	type WorkosAccount,
	signIn as workosSignIn,
	signOut as workosSignOut,
} from "../auth/workos.ts";
import { resetLocalMobileData } from "../lib/mobile-data.ts";
import {
	deleteAccount as deleteRelayAccount,
	resetRelayAccessToken,
} from "../rpc/relay-client.ts";
import { appAtomRegistry, batchAtomUpdates } from "./registry.tsx";

export const authHydratedAtom = Atom.make(false).pipe(Atom.keepAlive);
export const authAccountAtom = Atom.make<WorkosAccount | null>(null).pipe(
	Atom.keepAlive,
);
export const authBusyAtom = Atom.make(false).pipe(Atom.keepAlive);
export const authErrorAtom = Atom.make<string | null>(null).pipe(
	Atom.keepAlive,
);

const message = (cause: unknown): string => {
	const text = cause instanceof Error ? cause.message : String(cause);
	if (text === "workos_sign_in_cancelled")
		return "Remote sign-in was cancelled.";
	if (text.startsWith("workos_authenticate_")) {
		return "Remote access could not complete sign-in. Check the account setup and try again.";
	}
	return text;
};

export const hydrateAuth = async (): Promise<void> => {
	let account: WorkosAccount | null = null;
	try {
		account = await currentAccount();
	} catch {
		// Keychain access can be temporarily unavailable after an install or
		// while the device is locked. Startup must still settle to signed out.
	}
	batchAtomUpdates(() => {
		appAtomRegistry.set(authAccountAtom, account);
		appAtomRegistry.set(authHydratedAtom, true);
	});
};

export const signIn = async (): Promise<void> => {
	batchAtomUpdates(() => {
		appAtomRegistry.set(authBusyAtom, true);
		appAtomRegistry.set(authErrorAtom, null);
	});
	try {
		const account = await workosSignIn();
		batchAtomUpdates(() => {
			appAtomRegistry.set(authAccountAtom, account);
			appAtomRegistry.set(authBusyAtom, false);
		});
	} catch (cause) {
		batchAtomUpdates(() => {
			appAtomRegistry.set(authBusyAtom, false);
			appAtomRegistry.set(authErrorAtom, message(cause));
		});
	}
};

export const signOut = async (): Promise<void> => {
	await workosSignOut();
	resetRelayAccessToken();
	appAtomRegistry.set(authAccountAtom, null);
};

export const resetApp = async (): Promise<void> => {
	batchAtomUpdates(() => {
		appAtomRegistry.set(authBusyAtom, true);
		appAtomRegistry.set(authErrorAtom, null);
	});
	try {
		await resetLocalMobileData();
		batchAtomUpdates(() => {
			appAtomRegistry.set(authAccountAtom, null);
			appAtomRegistry.set(authBusyAtom, false);
			appAtomRegistry.set(authErrorAtom, null);
		});
	} catch (cause) {
		batchAtomUpdates(() => {
			appAtomRegistry.set(authBusyAtom, false);
			appAtomRegistry.set(authErrorAtom, message(cause));
		});
		throw cause;
	}
};

export const deleteAccount = async (): Promise<void> => {
	batchAtomUpdates(() => {
		appAtomRegistry.set(authBusyAtom, true);
		appAtomRegistry.set(authErrorAtom, null);
	});
	try {
		await deleteRelayAccount();
	} catch (cause) {
		batchAtomUpdates(() => {
			appAtomRegistry.set(authBusyAtom, false);
			appAtomRegistry.set(authErrorAtom, message(cause));
		});
		throw cause;
	}
	try {
		await resetLocalMobileData();
		batchAtomUpdates(() => {
			appAtomRegistry.set(authAccountAtom, null);
			appAtomRegistry.set(authBusyAtom, false);
			appAtomRegistry.set(authErrorAtom, null);
		});
	} catch (cause) {
		batchAtomUpdates(() => {
			appAtomRegistry.set(authAccountAtom, null);
			appAtomRegistry.set(authBusyAtom, false);
			appAtomRegistry.set(authErrorAtom, `Account deleted. ${message(cause)}`);
		});
	}
};
import { readFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { describe, expect, it } from "vitest";

import {
	defaultRelayBaseUrl,
	defaultWorkosClientId,
} from "../../src/auth/config";

describe("mobile relay configuration", () => {
	it("keeps development on staging and release builds on production", () => {
		expect(defaultWorkosClientId(true)).toBe(
			"REDACTED",
		);
		expect(defaultWorkosClientId(false)).toBe(
			"client_01KWGQ818571ARFATQ3G9AR2Y2",
		);
		expect(defaultRelayBaseUrl(true)).toBe("https://relay-staging.stuff.md");
		expect(defaultRelayBaseUrl(false)).toBe("https://relay.stuff.md");
	});

	it("pins internal builds to the staging identity and relay", async () => {
		const eas = JSON.parse(
			await readFile(
				resolve(dirname(fileURLToPath(import.meta.url)), "../../eas.json"),
				"utf8",
			),
		) as {
			readonly build: Readonly<
				Record<string, { readonly env?: Readonly<Record<string, string>> }>
			>;
		};
		for (const profile of ["development", "preview"]) {
			expect(eas.build[profile]?.env).toMatchObject({
				EXPO_PUBLIC_WORKOS_CLIENT_ID: "REDACTED",
				EXPO_PUBLIC_ZUSE_RELAY_URL: "https://relay-staging.stuff.md",
			});
		}
		expect(eas.build.production?.env?.EXPO_PUBLIC_WORKOS_CLIENT_ID).toBe(
			"client_01KWGQ818571ARFATQ3G9AR2Y2",
		);
	});
});
