	onTogglePin: (item: ChatItem) => void;
}) {
	const row = item.row;
	const isActive = row.status === "running" || row.status === "booting";
	const canPin = row.chat !== null;
	const href =
		`/c/${encodeURIComponent(row.connectionKey)}/session/${encodeURIComponent(
			row.session.id,
