import type { ProjectBundle } from "~/store/sessions";
import {
	projectAvatarUrl,
	visibleConnectionLabel,
	visibleProjectPath,
} from "./display-names";
import { connectionSessionKey } from "./session-key";

const INITIAL_VISIBLE_CHATS = 6;
const SHOW_MORE_STEP = 10;

export type InboxChatRow = {
	key: string;
	connectionKey: string;
	connectionLabel: string;
	projectId: Folder["id"];
	projectName: string;
	projectPath: string;
	chat: Chat | null;
	session: Session;
	title: string;
	/** Relative time since the last message ("2m", "3h", "Mon"). */
	subtitle: string;
	/** `"${providerId} / ${model}"` — kept off the visible row but searchable. */
	providerModel: string;
	status: SessionStatus;
	unread: boolean;
	pinned: boolean;
	threadCount: number;
	runningCount: number;
	threadLabel: string;
	updatedAt: number;
};

export type InboxProjectGroup = {
	key: string;
	connectionKey: string;
	connectionLabel: string;
	projectId: Folder["id"];
	title: string;
	path: string;
	displayPath: string;
	avatarUrl: string | null;
	rows: InboxChatRow[];
	unreadCount: number;
	activeCount: number;
	updatedAt: number;
};

export type InboxGroupDisplayState = {
	collapsed: boolean;
	visibleCount: number;
};

export const DEFAULT_INBOX_GROUP_DISPLAY: InboxGroupDisplayState = {
	collapsed: false,
	visibleCount: INITIAL_VISIBLE_CHATS,
};

export type InboxListItem =
	| {
			type: "header";
			key: string;
			group: InboxProjectGroup;
			collapsed: boolean;
			isFirst: boolean;
	  }
	| {
			type: "chat";
			key: string;
			row: InboxChatRow;
			isLast: boolean;
	  }
	| {
			type: "show-more";
			key: string;
			groupKey: string;
			hiddenCount: number;
			canShowLess: boolean;
	  };

export type InboxDisplayAction = "toggle-collapsed" | "show-more" | "show-less";

export const nextInboxGroupDisplay = (
	current: InboxGroupDisplayState,
	action: InboxDisplayAction,
): InboxGroupDisplayState => {
	switch (action) {
		case "toggle-collapsed":
			return { ...current, collapsed: !current.collapsed };
		case "show-more":
			return {
				...current,
				visibleCount: current.visibleCount + SHOW_MORE_STEP,
			};
		case "show-less":
			return DEFAULT_INBOX_GROUP_DISPLAY;
	}
