export default function HomeScreen() {
	const { width } = useWindowDimensions();
	const [search, setSearch] = useState("");
	const [displayStates, setDisplayStates] = useState<
		ReadonlyMap<string, InboxGroupDisplayState>
	>(() => new Map());
	const connectingEnvironmentIds = useRef(new Set<string>());
	const account = useAtomValue(authAccountAtom);
	const authHydrated = useAtomValue(authHydratedAtom);
	const busy = useAtomValue(authBusyAtom);
	const authError = useAtomValue(authErrorAtom);
	const connections = useAtomValue(connectionsAtom);
	const connectionsHydrated = useAtomValue(connectionsHydratedAtom);
	const environments = useAtomValue(environmentsAtom);
	const environmentsLoading = useAtomValue(environmentsLoadingAtom);
	const environmentsError = useAtomValue(environmentsErrorAtom);
	const connectionSnapshots = useAtomValue(snapshotsByConnectionAtom);
	const bundlesByConnection = useAtomValue(bundlesByConnectionAtom);
	const statusBySession = useAtomValue(statusBySessionAtom);
	const loadingByConnection = useAtomValue(loadingByConnectionAtom);
	const errorByConnection = useAtomValue(errorByConnectionAtom);
	const pinnedHydrated = useAtomValue(pinnedChatsHydratedAtom);
	const pinnedKeys = useAtomValue(pinnedChatKeysAtom);
	const reachableConnections = useMemo(
		() => availableConnections(connections, account !== null),
		[account, connections],
	);

	useEffect(() => {
		if (!authHydrated) void hydrateAuth();
	}, [authHydrated]);

	useEffect(() => {
		if (!connectionsHydrated) void hydrateConnections();
	}, [connectionsHydrated]);

	useEffect(() => {
		if (!pinnedHydrated) void hydratePinnedChats();
	}, [pinnedHydrated]);

	useEffect(() => {
		if (account !== null) void refreshEnvironments();
	}, [account]);

	useEffect(() => {
		if (account === null) return;
		for (const environment of environments) {
			const alreadyConnected = connections.some(
				(connection) =>
					connection.source === "relay" &&
					connection.environmentId === environment.environmentId,
			);
			if (
				environment.presence !== "online" ||
				alreadyConnected ||
				connectingEnvironmentIds.current.has(environment.environmentId)
			) {
				continue;
			}
			connectingEnvironmentIds.current.add(environment.environmentId);
			void connectToEnvironment(environment.environmentId).finally(() => {
				connectingEnvironmentIds.current.delete(environment.environmentId);
			});
		}
	}, [account, connections, environments]);

	useEffect(() => {
		const unwatch = reachableConnections.flatMap((connection) => {
			const options = optionsForConnection(connection.key, connections);
			return options === null ? [] : [watchConnection(connection.key, options)];
		});
		return () => {
			for (const stop of unwatch) stop();
		};
	}, [connections, reachableConnections]);

	useEffect(() => {
		for (const connection of reachableConnections) {
			const options = optionsForConnection(connection.key, connections);
			if (options === null) continue;
			void hydrateSessions(connection.key, options);
			void refreshConnectionLabel(connection.key, options);
		}
	}, [connections, reachableConnections]);

	useEffect(() => {
		for (const connection of reachableConnections) {
			const snapshot = connectionSnapshots[connection.key];
			if (snapshot?.status !== "connected") continue;
			const options = optionsForConnection(connection.key, connections);
			if (options === null) continue;
			void refreshSessionsAfterConnect(
				connection.key,
				options,
				snapshot.generation,
			);
		}
	}, [connectionSnapshots, connections, reachableConnections]);

	const searching = search.trim().length > 0;
	const groups = useMemo(
		() =>
			buildInboxGroups({
				connections: reachableConnections,
				bundlesByConnection,
				statusBySession,
				query: search,
				pinnedChatKeys: new Set(pinnedKeys),
			}),
		[
			bundlesByConnection,
			pinnedKeys,
			reachableConnections,
			search,
			statusBySession,
		],
	);
	const feed = useMemo(
		() => buildHomeFeed({ groups, displayStates, searching }),
		[displayStates, groups, searching],
	);
	const loading =
		!authHydrated ||
		!connectionsHydrated ||
		!pinnedHydrated ||
		(account !== null && environmentsLoading) ||
		reachableConnections.some(
			(connection) => loadingByConnection[connection.key] === true,
		);
	const connectionFailure =
		reachableConnections
			.map((connection) => {
				const snapshot = connectionSnapshots[connection.key];
				const failed =
					snapshot?.status === "error" || snapshot?.status === "blockedAuth";
				const error = failed
					? (snapshot.error ?? errorByConnection[connection.key])
					: snapshot === undefined
						? errorByConnection[connection.key]
						: null;
				return error ? ([connection.key, error] as const) : null;
			})
			.find((entry) => entry !== null) ?? null;
	const connectionError = connectionFailure?.[1] ?? null;
	const recoveringConnection = reachableConnections.find((connection) => {
		const status = connectionSnapshots[connection.key]?.status;
		return status === "connecting" || status === "reconnecting";
	});
	const retryFailedConnection = () => {
		if (connectionFailure === null) {
			if (account !== null) void refreshEnvironments();
			return;
		}
		const [key] = connectionFailure;
		const options = optionsForConnection(key, connections);
		if (options !== null) retryConnection(key, options);
	};
	const retryRecoveringConnection = () => {
		if (recoveringConnection === undefined) return;
		const options = optionsForConnection(recoveringConnection.key, connections);
		if (options !== null) retryConnection(recoveringConnection.key, options);
	};

	const updateGroup = useCallback((key: string, action: InboxDisplayAction) => {
		selectionTap();
		setDisplayStates((prev) => {
			const next = new Map(prev);
			next.set(
				key,
				nextInboxGroupDisplay(
					prev.get(key) ?? DEFAULT_INBOX_GROUP_DISPLAY,
					action,
				),
			);
			return next;
		});
	}, []);

	const onArchiveRow = useCallback(
		async (item: ChatFeedItem) => {
			const options = optionsForConnection(item.row.connectionKey, connections);
			if (options === null) return;
			successTap();
			if (item.row.chat !== null) {
				await archiveChat(item.row.connectionKey, options, item.row.chat.id);
			} else {
				await archiveSession(
					item.row.connectionKey,
					options,
					item.row.session.id,
				);
			}
		},
		[connections],
	);

	const onTogglePinRow = useCallback((item: ChatFeedItem) => {
		if (item.row.chat === null) return;
		selectionTap();
		void togglePinnedChat(
			pinnedChatKey(item.row.connectionKey, String(item.row.chat.id)),
		);
	}, []);

	const renderItem = ({ item }: { item: HomeFeedItem }) => {
		switch (item.type) {
			case "section-header":
				return <HomeSectionHeader title={item.title} />;
			case "project-header":
				return (
					<HomeProjectHeader
						group={item.group}
						collapsed={item.collapsed}
						connections={reachableConnections}
						onToggle={() => updateGroup(item.group.key, "toggle-collapsed")}
					/>
				);
			case "show-more":
				return (
					<View className="flex-row gap-1 px-3 py-1 pl-10">
						{item.hiddenCount > 0 ? (
							<Button
								size="sm"
								variant="ghost"
								onPress={() => updateGroup(item.groupKey, "show-more")}
							>
								{`Show ${item.hiddenCount} more`}
							</Button>
						) : null}
						{item.canShowLess ? (
							<Button
								size="sm"
								variant="ghost"
								onPress={() => updateGroup(item.groupKey, "show-less")}
							>
								Show less
							</Button>
						) : null}
					</View>
				);
			case "chat":
				return (
					<HomeChatRow
						item={item}
						onArchive={onArchiveRow}
						onTogglePin={onTogglePinRow}
					/>
				);
		}
	};

	if (!authHydrated || !connectionsHydrated) {
		return (
			<View className="flex-1 bg-background px-4 pt-28">
				<HomeSkeleton />
			</View>
		);
	}

	return (
		<>
			<Stack.Screen
				options={{
					title: "Zuse",
					headerLargeTitle: false,
					headerTitle: () => <BrandTitle />,
					headerRight: () => (
						<View className="flex-row items-center gap-5">
							<Pressable
								accessibilityRole="button"
								accessibilityLabel="Pair with desktop"
								hitSlop={12}
								onPress={() => router.push("/connect/scan")}
							>
								<HugeIcon icon={QrCodeIcon} size={21} color={colors.accent} />
							</Pressable>
							<Pressable
								accessibilityRole="button"
								accessibilityLabel="Open settings"
								hitSlop={12}
								onPress={() => router.push("/settings")}
							>
								<HugeIcon
									icon={Settings01Icon}
									size={22}
									color={colors.accent}
								/>
							</Pressable>
						</View>
					),
				}}
			/>
			<Stack.Toolbar placement="bottom">
				<Stack.Toolbar.View separateBackground>
					<GlassSurface
						style={{
							width: Math.min(width - 88, 520),
							minHeight: 44,
							flexDirection: "row",
							alignItems: "center",
							gap: 9,
							paddingHorizontal: 14,
							paddingVertical: 8,
						}}
					>
						<Search size={17} color={colors.secondaryFg} />
						<TextInput
							accessibilityLabel="Search chats"
							autoCapitalize="none"
							autoCorrect={false}
							className="min-h-7 flex-1 font-sans text-[16px] text-foreground"
							placeholder="Search"
							placeholderTextColor={colors.tertiaryFg}
							returnKeyType="search"
							value={search}
							onChangeText={setSearch}
						/>
						{searching ? (
							<Pressable
								accessibilityRole="button"
								accessibilityLabel="Clear search"
								hitSlop={8}
								onPress={() => setSearch("")}
							>
								<HugeIcon
									icon={Cancel01Icon}
									size={15}
									color={colors.secondaryFg}
								/>
							</Pressable>
						) : null}
					</GlassSurface>
				</Stack.Toolbar.View>
				<Stack.Toolbar.Button
					icon="square.and.pencil"
					separateBackground
					onPress={() => router.push("/new-chat")}
				/>
			</Stack.Toolbar>
			<FlatList
				className="flex-1 bg-background"
				data={feed}
				keyExtractor={(item) => item.key}
				renderItem={renderItem}
				contentInsetAdjustmentBehavior="automatic"
				contentContainerClassName="px-4 pb-28 pt-2"
				initialNumToRender={12}
				windowSize={7}
				removeClippedSubviews
				keyboardDismissMode="on-drag"
				keyboardShouldPersistTaps="handled"
				refreshControl={
					<RefreshControl
						refreshing={loading && feed.length > 0}
						tintColor={colors.accent}
						onRefresh={() => {
							if (account !== null) void refreshEnvironments();
							for (const connection of reachableConnections) {
								const options = optionsForConnection(
									connection.key,
									connections,
								);
								if (options !== null)
									void hydrateSessions(connection.key, options);
							}
						}}
					/>
				}
				ListHeaderComponent={
					((account === null ? null : environmentsError) ?? connectionError) ? (
						<View className="mb-3">
							<ConnectionRecoveryBanner
								message={connectionErrorMessage(
									(account === null ? null : environmentsError) ??
										connectionError,
								)}
								onRetry={retryFailedConnection}
								onPairAgain={() => router.push("/connect/scan")}
import {
	orderedChatSessions,
	resolveActiveChatSession,
} from "@zuse/client-runtime/chat-threads";
import type { Chat, Folder, Session, SessionStatus } from "@zuse/contracts";

import type { ConnectionRecord } from "~/store/connections";
import type { ProjectBundle } from "~/store/sessions";
import {
	projectAvatarUrl,
	visibleConnectionLabel,
	visibleProjectPath,
} from "./display-names";
import { connectionSessionKey } from "./session-key";

const INITIAL_VISIBLE_CHATS = 6;
const SHOW_MORE_STEP = 10;

export type InboxChatRow = {
	key: string;
	connectionKey: string;
	connectionLabel: string;
	projectId: Folder["id"];
	projectName: string;
	projectPath: string;
	chat: Chat | null;
	session: Session;
	title: string;
	/** Relative time since the last message ("2m", "3h", "Mon"). */
	subtitle: string;
	/** `"${providerId} / ${model}"` — kept off the visible row but searchable. */
	providerModel: string;
	status: SessionStatus;
	unread: boolean;
	pinned: boolean;
	threadCount: number;
	runningCount: number;
	threadLabel: string;
	updatedAt: number;
};

export type InboxProjectGroup = {
	key: string;
	connectionKey: string;
	connectionLabel: string;
	projectId: Folder["id"];
	title: string;
	path: string;
	displayPath: string;
	avatarUrl: string | null;
	rows: InboxChatRow[];
	unreadCount: number;
	activeCount: number;
	updatedAt: number;
};

export type InboxGroupDisplayState = {
	collapsed: boolean;
	visibleCount: number;
};

export const DEFAULT_INBOX_GROUP_DISPLAY: InboxGroupDisplayState = {
	collapsed: false,
	visibleCount: INITIAL_VISIBLE_CHATS,
};

export type InboxListItem =
	| {
			type: "header";
			key: string;
			group: InboxProjectGroup;
			collapsed: boolean;
			isFirst: boolean;
	  }
	| {
			type: "chat";
			key: string;
			row: InboxChatRow;
			isLast: boolean;
	  }
	| {
			type: "show-more";
			key: string;
			groupKey: string;
			hiddenCount: number;
			canShowLess: boolean;
	  };

export type InboxDisplayAction = "toggle-collapsed" | "show-more" | "show-less";

export const nextInboxGroupDisplay = (
	current: InboxGroupDisplayState,
	action: InboxDisplayAction,
): InboxGroupDisplayState => {
	switch (action) {
		case "toggle-collapsed":
			return { ...current, collapsed: !current.collapsed };
		case "show-more":
			return {
				...current,
				visibleCount: current.visibleCount + SHOW_MORE_STEP,
			};
		case "show-less":
			return DEFAULT_INBOX_GROUP_DISPLAY;
	}
};

export const buildInboxGroups = ({
	connections,
	bundlesByConnection,
	statusBySession,
	query,
	pinnedChatKeys = new Set<string>(),
}: {
	connections: readonly ConnectionRecord[];
	bundlesByConnection: Record<string, readonly ProjectBundle[]>;
	statusBySession: Record<string, SessionStatus>;
	query: string;
	pinnedChatKeys?: ReadonlySet<string>;
}): InboxProjectGroup[] => {
	const normalizedQuery = query.trim().toLowerCase();
	const groups: InboxProjectGroup[] = [];

	for (const connection of connections) {
		const bundles = bundlesByConnection[connection.key] ?? [];
		for (const bundle of bundles) {
			const rows = buildRowsForProject({
				connection,
				bundle,
				statusBySession,
				pinnedChatKeys,
			}).filter((row) => matchesQuery(row, normalizedQuery));
			if (rows.length === 0) continue;

			rows.sort(compareRows);
			groups.push({
				key: `${connection.key}:${bundle.project.id}`,
				connectionKey: connection.key,
				connectionLabel: visibleConnectionLabel(connection.label),
				projectId: bundle.project.id,
				title: bundle.project.name,
				path: bundle.project.path,
				displayPath: visibleProjectPath(bundle.project.path),
				avatarUrl: projectAvatarUrl(bundle.project.path, bundle.project.name),
				rows,
				unreadCount: rows.filter((row) => row.unread).length,
				activeCount: rows.filter((row) => isActiveStatus(row.status)).length,
				updatedAt: Math.max(...rows.map((row) => row.updatedAt), 0),
			});
		}
	}

	return groups.sort(
		(a, b) => b.updatedAt - a.updatedAt || a.title.localeCompare(b.title),
	);
};

export const buildInboxListItems = ({
	groups,
	displayStates,
	searching,
}: {
	groups: readonly InboxProjectGroup[];
	displayStates: ReadonlyMap<string, InboxGroupDisplayState>;
	searching: boolean;
}): InboxListItem[] => {
	const items: InboxListItem[] = [];
	for (const [index, group] of groups.entries()) {
		const display = displayStates.get(group.key) ?? DEFAULT_INBOX_GROUP_DISPLAY;
		const collapsed = display.collapsed && !searching;
		items.push({
			type: "header",
			key: `header:${group.key}`,
			group,
			collapsed,
			isFirst: index === 0,
		});
		if (collapsed) continue;

		const visibleCount = searching
			? group.rows.length
			: Math.min(display.visibleCount, group.rows.length);
		const visibleRows = group.rows.slice(0, visibleCount);
		const hiddenCount = group.rows.length - visibleCount;

		for (const [rowIndex, row] of visibleRows.entries()) {
			items.push({
				type: "chat",
				key: row.key,
				row,
				isLast: rowIndex === visibleRows.length - 1 && hiddenCount === 0,
			});
		}

		if (!searching && group.rows.length > INITIAL_VISIBLE_CHATS) {
			items.push({
				type: "show-more",
				key: `show-more:${group.key}`,
				groupKey: group.key,
				hiddenCount,
				canShowLess: visibleCount > INITIAL_VISIBLE_CHATS,
			});
		}
	}
	return items;
};

const buildRowsForProject = ({
	connection,
	bundle,
	statusBySession,
	pinnedChatKeys,
}: {
	connection: ConnectionRecord;
	bundle: ProjectBundle;
	statusBySession: Record<string, SessionStatus>;
	pinnedChatKeys: ReadonlySet<string>;
}): InboxChatRow[] => {
	const rows: InboxChatRow[] = [];
	const sessionsByChat = new Map<string, Session[]>();
	for (const session of bundle.sessions) {
		const list = sessionsByChat.get(session.chatId) ?? [];
		list.push(session);
		sessionsByChat.set(session.chatId, list);
	}

	for (const chat of bundle.chats) {
		if (chat.archivedAt !== null) continue;
		const sessions = orderedChatSessions(
			sessionsByChat.get(chat.id) ?? [],
			chat.id,
		);
		const session = resolveActiveChatSession(chat, sessions);
		if (session === null) continue;
		rows.push(
			rowForSession({
				connection,
				bundle,
				session,
				chat,
				statusBySession,
				pinnedChatKeys,
				siblingSessions: sessions,
			}),
		);
	}

	const chatIds = new Set(bundle.chats.map((chat) => chat.id));
	for (const session of bundle.sessions) {
		if (session.archivedAt !== null) continue;
		if (chatIds.has(session.chatId)) continue;
		rows.push(
			rowForSession({
				connection,
				bundle,
				session,
				chat: null,
				statusBySession,
				pinnedChatKeys,
				siblingSessions: [session],
			}),
		);
	}

	return rows;
};

const rowForSession = ({
	connection,
	bundle,
	session,
	chat,
	statusBySession,
	pinnedChatKeys,
	siblingSessions,
}: {
	connection: ConnectionRecord;
	bundle: ProjectBundle;
	session: Session;
	chat: Chat | null;
	statusBySession: Record<string, SessionStatus>;
	pinnedChatKeys: ReadonlySet<string>;
	siblingSessions: readonly Session[];
}): InboxChatRow => {
	const selectedStatus =
		statusBySession[connectionSessionKey(connection.key, session.id)] ??
		session.status;
	const siblingStatuses = siblingSessions.map(
		(item) =>
			statusBySession[connectionSessionKey(connection.key, item.id)] ??
			item.status,
	);
	const runningCount = siblingStatuses.filter(
		(item) => item === "running",
	).length;
	const status: SessionStatus =
		runningCount > 0
			? "running"
			: siblingStatuses.includes("booting")
				? "booting"
