		groups,
		displayStates,
		searching,
	}).map((item) => {
		switch (item.type) {
			case "header":
				return {
					type: "project-header",
					key: item.key,
					group: item.group,
					collapsed: item.collapsed,
				};
			case "chat":
				return {
					type: "chat",
					key: `project:${item.key}`,
					row: item.row,
					context: "project",
					showProject: false,
					isFirst: false,
					isLast: item.isLast,
				};
			case "show-more":
				return item;
		}
	});

	if (searching) return projectItems;

	const allRows = groups.flatMap((group) => group.rows);
	const pinned = allRows.filter((row) => row.pinned).sort(byUpdatedAt);
	const active = allRows
		.filter((row) => !row.pinned && isActive(row))
		.sort(byUpdatedAt);
	const recent = allRows
		.filter((row) => !row.pinned && !isActive(row))
		.sort(byUpdatedAt)
		.slice(0, recentLimit);

	const items: HomeFeedItem[] = [
		...flatSection("Pinned", "pinned", pinned),
		...flatSection("Active", "active", active),
		...flatSection("Recent", "recent", recent),
	];
	if (projectItems.length > 0) {
		items.push({
			type: "section-header",
			key: "section:Projects",
			title: "Projects",
		});
		items.push(...projectItems);
	}
	return items;
};
