import type {
	Chat,
	Folder,
	FolderId,
	GitOriginInfo,
	ProviderId,
	Session,
} from "@zuse/contracts";
import type {
	CatalogConnectionStatus,
	EnvironmentCatalogEntry,
} from "../store/environment-catalog.ts";
import type { EnvironmentShellData } from "./environment-shell-client-bus.ts";

/**
 * Display-only grouping of the environment catalog: the same repository
 * checked out on several computers collapses into ONE logical project row.
 * Computers never form sections — they are a per-member property.
 */
export type LogicalProjectMember = {
	readonly environmentId: string;
	readonly environmentLabel: string;
	readonly connectionKind: EnvironmentCatalogEntry["connectionKind"];
	readonly status: CatalogConnectionStatus;
	readonly folderId: FolderId;
	readonly folderName: string;
	readonly isActive: boolean;
	/** True when this member lives on this physical desktop. */
	readonly local: boolean;
	readonly connected: boolean;
};

export type LogicalChatRef = {
	readonly chat: Chat;
	readonly environmentId: string;
	readonly environmentLabel: string;
	/**
	 * True when the chat lives on a different physical machine than this
	 * desktop. Anchored to the immutable local environment id — it never
	 * changes when the active environment does.
	 */
	readonly remote: boolean;
	/** True when the ref came from the ACTIVE environment's live stores. */
	readonly live: boolean;
	/**
	 * True when any session of this chat is booting/running. Only computed for
	 * catalog refs — active-environment rows derive activity from live stores.
	 */
	readonly busy: boolean;
	/** Provider/model for the selected (or newest) session, when known. */
	readonly providerId: ProviderId | null;
	readonly model: string | null;
};

export type LogicalProjectGroup = {
	readonly key: string;
	readonly displayName: string;
	readonly origin: GitOriginInfo | null;
	readonly members: ReadonlyArray<LogicalProjectMember>;
	/** Merged across members, newest `updatedAt` first. Archived chats excluded. */
	readonly chats: ReadonlyArray<LogicalChatRef>;
	readonly environmentPresence: "local-only" | "remote-only" | "mixed";
};

/** Where a NEW chat should run: a member of the selected logical project. */
export type NewChatTarget = {
	readonly environmentId: string;
	/** Null means the computer is selected but this project must be cloned first. */
	readonly folderId: FolderId | null;
};

const originKeyOf = (origin: GitOriginInfo | null): string | null =>
	origin === null ? null : `${origin.host}/${origin.owner}/${origin.repo}`;

const isChatBusy = (chat: Chat, sessions: ReadonlyArray<Session>): boolean =>
	sessions.some(
		(session) =>
			session.chatId === chat.id &&
			(session.status === "booting" || session.status === "running"),
	);

const representativeSession = (
	chat: Chat,
	sessions: ReadonlyArray<Session>,
): Session | null => {
	const candidates = sessions.filter((session) => session.chatId === chat.id);
	return (
		candidates.find((session) => session.id === chat.activeSessionId) ??
		candidates.toSorted(
			(left, right) => right.updatedAt.getTime() - left.updatedAt.getTime(),
		)[0] ??
		null
	);
};

type MutableGroup = {
	key: string;
	origin: GitOriginInfo | null;
	members: LogicalProjectMember[];
	chats: LogicalChatRef[];
	/** Workspace-order index of the first active-env member, if any. */
	activeOrder: number | null;
};

type MemberSource = {
	readonly environmentId: string;
	readonly environmentLabel: string;
	readonly connectionKind: EnvironmentCatalogEntry["connectionKind"];
	readonly status: CatalogConnectionStatus;
	readonly isActive: boolean;
	readonly folder: Folder;
	readonly origin: GitOriginInfo | null;
	readonly chats: ReadonlyArray<Chat>;
	readonly sessions: ReadonlyArray<Session>;
	readonly activeOrder: number | null;
};

export const buildLogicalProjectGroups = (input: {
	readonly entries: ReadonlyArray<EnvironmentCatalogEntry>;
	readonly activeEnvironmentId: string;
	/**
	 * The immutable id of this physical desktop's environment. "Remote"
	 * badges compare against THIS, never the active environment, so the
	 * sidebar reads identically no matter which computer is active.
	 */
	readonly localEnvironmentId: string;
	/** Live workspace-store folders for the ACTIVE environment (catalog may lag). */
	readonly activeFolders: ReadonlyArray<Folder>;
	readonly activeOrigins: Readonly<Record<string, GitOriginInfo | null>>;
	readonly activeChatsByProject: Readonly<Record<string, ReadonlyArray<Chat>>>;
	/** Qualified ClientBus shell data; the connection catalog owns no entities. */
	readonly shellsByEnvironment: Readonly<
		Record<string, EnvironmentShellData | null>
	>;
}): ReadonlyArray<LogicalProjectGroup> => {
	const groups: MutableGroup[] = [];
	const groupsByOrigin = new Map<string, MutableGroup[]>();

	const addMember = (source: MemberSource): void => {
		const local = source.environmentId === input.localEnvironmentId;
		const member: LogicalProjectMember = {
			environmentId: source.environmentId,
			environmentLabel: source.environmentLabel,
			connectionKind: source.connectionKind,
			status: source.status,
			folderId: source.folder.id,
			folderName: source.folder.name,
			isActive: source.isActive,
			local,
			connected: source.status === "connected",
		};
		const chatRefs: LogicalChatRef[] = source.chats
			.filter((chat) => chat.archivedAt === null)
			.map((chat) => {
				const session = representativeSession(chat, source.sessions);
				return {
					chat,
					environmentId: source.environmentId,
					environmentLabel: source.environmentLabel,
					remote: !local,
					live: source.isActive,
					busy: source.isActive ? false : isChatBusy(chat, source.sessions),
					providerId: session?.providerId ?? null,
					model: session?.model ?? null,
				};
			});
		const originKey = originKeyOf(source.origin);
		if (originKey !== null) {
			const candidates = groupsByOrigin.get(originKey) ?? [];
			// Two checkouts of the same repo on ONE environment stay separate
			// rows — merging is strictly across computers.
			const target = candidates.find(
				(candidate) =>
					!candidate.members.some(
						(existing) => existing.environmentId === source.environmentId,
					),
			);
			if (target !== undefined) {
				target.members.push(member);
				target.chats.push(...chatRefs);
				if (target.activeOrder === null && source.activeOrder !== null) {
					target.activeOrder = source.activeOrder;
				}
				return;
			}
			const created: MutableGroup = {
				key:
					candidates.length === 0
						? originKey
						: `${originKey}\u0001${source.environmentId}:${source.folder.id}`,
				origin: source.origin,
				members: [member],
				chats: chatRefs,
				activeOrder: source.activeOrder,
			};
			candidates.push(created);
			groupsByOrigin.set(originKey, candidates);
			groups.push(created);
			return;
		}
		// Originless folders NEVER merge.
		groups.push({
			key: `${source.environmentId}:${source.folder.id}`,
			origin: null,
			members: [member],
			chats: chatRefs,
			activeOrder: source.activeOrder,
		});
	};

	const activeEntry = input.entries.find(
		(entry) => entry.environmentId === input.activeEnvironmentId,
	);
	// The active environment's data comes from the LIVE stores; its catalog
	// entry only lends connection metadata.
	input.activeFolders.forEach((folder, index) => {
		addMember({
			environmentId: input.activeEnvironmentId,
			environmentLabel: activeEntry?.label ?? "This computer",
			connectionKind: activeEntry?.connectionKind ?? "local",
			status: "connected",
			isActive: true,
			folder,
			origin: input.activeOrigins[folder.id] ?? null,
			chats: input.activeChatsByProject[folder.id] ?? [],
			sessions: [],
			activeOrder: index,
		});
	});
	for (const entry of input.entries) {
		if (entry.environmentId === input.activeEnvironmentId) continue;
		const shell = input.shellsByEnvironment[entry.environmentId];
		if (shell === null || shell === undefined) continue;
		for (const folder of shell.folders) {
			addMember({
				environmentId: entry.environmentId,
				environmentLabel: entry.label,
				connectionKind: entry.connectionKind,
				status: entry.status,
				isActive: false,
				folder,
				origin: shell.originsByFolder[folder.id] ?? null,
				chats: shell.chatsByProject[folder.id] ?? [],
				sessions: shell.sessionsByProject[folder.id] ?? [],
				activeOrder: null,
			});
		}
	}

	const finished = groups.map((group): LogicalProjectGroup => {
		const members = [...group.members].sort(
			(left, right) =>
				Number(right.isActive) - Number(left.isActive) ||
				Number(right.connected) - Number(left.connected),
		);
		const activeMember = members.find((member) => member.isActive);
		const displayName =
			activeMember?.folderName ??
			members.find((member) => member.connected)?.folderName ??
			members[0]?.folderName ??
			"";
		const localCount = members.filter((member) => member.local).length;
		return {
			key: group.key,
			displayName,
			origin: group.origin,
			members,
			chats: [...group.chats].sort(
				(left, right) =>
					right.chat.updatedAt.getTime() - left.chat.updatedAt.getTime(),
			),
			environmentPresence:
				localCount === members.length
					? "local-only"
					: localCount === 0
						? "remote-only"
						: "mixed",
		};
	});

	// Groups anchored in the active workspace keep its order; the rest follow
	// alphabetically so remote-only repos have a stable, scannable position.
	return finished
		.map((group, index) => ({
			group,
			order: groups[index]?.activeOrder ?? null,
		}))
		.sort((left, right) => {
			if (left.order !== null && right.order !== null)
				return left.order - right.order;
			if (left.order !== null) return -1;
			if (right.order !== null) return 1;
			return left.group.displayName.localeCompare(right.group.displayName);
		})
		.map(({ group }) => group);
};

/**
 * The member a plain "open this project" action should land on: the active
 * environment first, then the first connected computer.
 */
export const preferredGroupMember = (
	group: LogicalProjectGroup,
): LogicalProjectMember | null =>
	group.members.find((member) => member.isActive) ??
	group.members.find((member) => member.connected) ??
	null;

/**
 * Where a new chat runs unless the user picks otherwise: this desktop's
 * member of the group when present, else the first connected member.
 */
export const defaultNewChatTarget = (
	group: LogicalProjectGroup,
): NewChatTarget | null => {
	const member =
		group.members.find((candidate) => candidate.local) ??
		group.members.find((candidate) => candidate.connected) ??
		null;
	return member === null
		? null
		: { environmentId: member.environmentId, folderId: member.folderId };
};

export type ComputerPickerItem = {
	readonly environmentId: string;
	readonly folderId: FolderId | null;
	readonly label: string;
	readonly status: CatalogConnectionStatus;
	readonly projectAvailable: boolean;
	readonly setupAvailable: boolean;
	readonly retryable: boolean;
	readonly selected: boolean;
	readonly disabled: boolean;
};

export type ComputerPickerModel =
	| { readonly kind: "hidden"; readonly item: ComputerPickerItem }
	| { readonly kind: "static"; readonly item: ComputerPickerItem }
	| {
			readonly kind: "menu";
			readonly items: ReadonlyArray<ComputerPickerItem>;
	  };

/**
 * "Run on" options for a logical project group. Selection reflects the
 * draft's target only — picking never touches global state. Hidden when
 * there is nothing to choose (single member on this desktop); a
 * non-interactive static label when the only member is remote; otherwise a
 * menu with this desktop first and non-connected members disabled.
 */
export const computerPickerItems = (
	group: LogicalProjectGroup,
	target: NewChatTarget | null,
	entries: ReadonlyArray<EnvironmentCatalogEntry> = [],
): ComputerPickerModel => {
	const resolved = target ?? defaultNewChatTarget(group);
	const memberItems = [...group.members]
		.sort(
			(left, right) =>
				Number(right.local) - Number(left.local) ||
				Number(right.connected) - Number(left.connected),
		)
		.map(
			(member): ComputerPickerItem => ({
				environmentId: member.environmentId,
				folderId: member.folderId,
				label:
					member.connectionKind === "local"
						? "This computer"
						: member.environmentLabel,
				status: member.status,
				projectAvailable: true,
				setupAvailable: false,
				retryable: member.status === "error" || member.status === "offline",
				selected:
					resolved !== null &&
					member.environmentId === resolved.environmentId &&
					member.folderId === resolved.folderId,
				disabled:
					!member.connected &&
					member.status !== "error" &&
					member.status !== "offline",
			}),
		);
	const representedEnvironmentIds = new Set(
		memberItems.map((item) => item.environmentId),
	);
	const catalogItems = entries
		.filter(
		if (CLOUD_WORKSPACE_BETA_AVAILABLE) void hydrateCloudChats();
	}, [hydrateCloudChats]);

	const desktopCatalogEnabled = window.zuse?.ssh !== undefined;

	useEffect(() => {
		void initializeEnvironmentCatalog().catch((cause) =>
			console.error("[zuse] environment catalog initialize failed", cause),
		);
	}, [initializeEnvironmentCatalog]);

	// Auto-expand the selected project so newly opened workspaces immediately
	// reveal their session list.
	useEffect(() => {
		if (selectedFolderId === null) return;
		const key = environmentProjectKey(activeEnvironmentId, selectedFolderId);
		setExpanded((prev) => (prev[key] ? prev : { ...prev, [key]: true }));
	}, [activeEnvironmentId, selectedFolderId]);

	// PR state is keyed per-session by `(folderId, worktreeId)` because each
	// worktree has its own branch and therefore its own PR. Hydration happens
	// inside `SessionRow` so each row pulls the entry that matches its
	// session — no per-project bulk hydrate.

	const onToggleKey = (key: string) => {
		setExpanded((previous) => ({ ...previous, [key]: !previous[key] }));
	};
	const onToggleExpanded = (environmentId: string, id: FolderId) => {
		onToggleKey(environmentProjectKey(environmentId, id));
	};

	const showComputerControls =
		desktopCatalogEnabled &&
		catalogEntries.filter((entry) => entry.status === "connected").length > 1;

	// One merged timeline: computers never form sections. The same repo across
	// machines collapses into one logical group; the computer is a row property.
	const logicalGroups = useMemo(
		() =>
			desktopCatalogEnabled
				? buildLogicalProjectGroups({
						entries: catalogEntries,
						activeEnvironmentId,
						localEnvironmentId: getLocalEnvironmentId(),
						activeFolders: folders,
						activeOrigins: origins,
						activeChatsByProject: chatsByProject,
						shellsByEnvironment: Object.fromEntries(
							Object.entries(shellViews).map(([environmentId, view]) => [
								environmentId,
								view.data,
							]),
						),
					})
				: [],
		[
			desktopCatalogEnabled,
			catalogEntries,
			activeEnvironmentId,
			folders,
			origins,
			chatsByProject,
			shellViews,
		],
	);
	const catalogViewState = environmentCatalogViewState({
		initialized: catalogInitialized,
		initializing: catalogInitializing,
		initializationError: catalogInitializationError,
		projectCount: logicalGroups.length,
		projectsLoading: loading,
	});

	return (
		<aside
			ref={paneRef}
			data-pane="sidebar"
			tabIndex={-1}
			className="flex h-full min-h-0 w-full flex-col bg-sidebar text-sidebar-foreground outline-none"
		>
			{desktopCatalogEnabled ? null : (
				<Suspense
					fallback={
						<div className="h-[60px] border-b border-sidebar-border/40" />
					}
				>
					<ComputerSwitcher />
				</Suspense>
			)}
			<SidebarActions />
			{showComputerControls ? (
				<div className="flex items-center justify-between px-2.5 py-1.5 text-[12px] text-muted-foreground">
					<span>Computers</span>
					<Suspense fallback={<span className="size-8" />}>
						<ComputerSwitcher />
					</Suspense>
				</div>
			) : null}
			<div className="flex items-center justify-between px-2.5 py-1.5 text-[12px] text-muted-foreground">
				<span>Projects</span>
				<ProjectAddMenu />
			</div>
			{showComputerControls ? (
				<CatalogConnectionNotice entries={catalogEntries} />
			) : null}
			<SidebarErrorToasts />

			<ul className="flex flex-1 flex-col gap-0.5 overflow-y-auto p-1.5">
				{desktopCatalogEnabled ? (
					<>
						{catalogViewState === "loading" ? (
							<li
								className="flex items-center justify-center gap-2 px-3 py-4 text-[13px] text-muted-foreground"
								aria-busy="true"
							>
								<Spinner className="size-3.5" />
								Loading projects…
							</li>
						) : null}
						{catalogViewState === "unavailable" ? (
							<li className="px-3 py-4 text-center text-[13px] text-muted-foreground">
								<p role="alert">This computer couldn’t load its projects.</p>
								<p className="mt-1 text-[12px]">{catalogInitializationError}</p>
								<button
									type="button"
									className="mt-2 rounded-md border border-sidebar-border px-2.5 py-1 text-[12px] text-sidebar-foreground hover:bg-sidebar-accent"
									onClick={() => {
										void initializeEnvironmentCatalog().catch(() => undefined);
									}}
								>
									Retry
								</button>
							</li>
						) : null}
						{catalogViewState === "empty" ? (
							<li className="px-3 py-4 text-center text-[13px] text-muted-foreground">
								No projects yet. Click + to add one.
							</li>
						) : null}
						{logicalGroups.map((group) => {
							const activeMember = group.members.find(
								(member) => member.isActive,
							);
							const folder =
								activeMember === undefined
									? undefined
									: folders.find((f) => f.id === activeMember.folderId);
							if (activeMember !== undefined && folder !== undefined) {
								return (
									<ProjectGroup
										key={group.key}
										id={folder.id}
										name={folder.name}
										path={folder.path}
										origin={origins[folder.id] ?? null}
										isExpanded={
											expanded[
												environmentProjectKey(activeEnvironmentId, folder.id)
											] === true
										}
										chats={chatsByProject[folder.id] ?? []}
										projectSessions={sessionsByProject[folder.id] ?? []}
										remoteChats={remoteChatRows(group)}
										cloudChats={cloudChats.filter(
											(chat) =>
												chat.repositoryIdentity ===
												repositoryIdentityForOrigin(origins[folder.id]),
										)}
										environmentId={EnvironmentId.make(activeEnvironmentId)}
										onSelect={() => void select(folder.id)}
										onToggleExpanded={() =>
											onToggleExpanded(activeEnvironmentId, folder.id)
										}
										onRemove={() => void remove(folder.id)}
									/>
								);
							}
							return (
								<LogicalCatalogGroup
									key={group.key}
									group={group}
									isExpanded={expanded[group.key] === true}
									onToggle={() => onToggleKey(group.key)}
								/>
							);
						})}
					</>
				) : (
					<>
						{folders.length === 0 && !loading ? (
							<li className="px-3 py-4 text-center text-[13px] text-muted-foreground">
								No projects yet. Click + to add one.
							</li>
						) : null}
						{folders.map((folder) => (
							<ProjectGroup
								key={folder.id}
								id={folder.id}
								name={folder.name}
								path={folder.path}
								origin={origins[folder.id] ?? null}
								isExpanded={
									expanded[
										environmentProjectKey(activeEnvironmentId, folder.id)
									] === true
								}
								chats={chatsByProject[folder.id] ?? []}
								projectSessions={sessionsByProject[folder.id] ?? []}
								cloudChats={cloudChats.filter(
									(chat) =>
										chat.repositoryIdentity ===
										repositoryIdentityForOrigin(origins[folder.id]),
								)}
								environmentId={EnvironmentId.make(activeEnvironmentId)}
								onSelect={() => void select(folder.id)}
								onToggleExpanded={() =>
									onToggleExpanded(activeEnvironmentId, folder.id)
								}
								onRemove={() => void remove(folder.id)}
							/>
						))}
import type {
	Chat,
	Folder,
	Message,
	PermissionMode,
	ProviderId,
	RuntimeMode,
	Session,
	SessionStatus,
	WorktreeId,
} from "@zuse/contracts";
import { Effect, Fiber, Stream } from "effect";
import { Atom } from "effect/unstable/reactivity";
import { connectionErrorMessage } from "~/lib/connection-error-message";
import { createConnectionRefreshCoordinator } from "~/lib/connection-refresh-coordinator";
import { connectionSessionKey } from "~/lib/session-key";
import { readSessionsSnapshot, writeSessionsSnapshot } from "~/offline/cache";
import {
	markChatRead as markChatReadRpc,
	renameChat as renameChatRpc,
	renameSession as renameSessionRpc,
	setSessionPermissionMode as setSessionPermissionModeRpc,
	setSessionRuntimeMode as setSessionRuntimeModeRpc,
} from "~/rpc/actions";
import {
	getConnectionClient,
	reportConnectionFailure,
	retryConnectionNow,
} from "~/rpc/connection";
import type { WsProtocolOptions } from "~/rpc/ws-protocol";

import { messagesBySessionAtom } from "./messages";
import { appAtomRegistry, batchAtomUpdates } from "./registry";

export type ProjectBundle = {
	project: Folder;
	chats: readonly Chat[];
	sessions: readonly Session[];
};

export const bundlesByConnectionAtom = Atom.make<
	Record<string, ProjectBundle[]>
>({}).pipe(Atom.keepAlive);
export const statusBySessionAtom = Atom.make<Record<string, SessionStatus>>(
	{},
).pipe(Atom.keepAlive);
export const errorByConnectionAtom = Atom.make<Record<string, string | null>>(
	{},
).pipe(Atom.keepAlive);
export const loadingByConnectionAtom = Atom.make<Record<string, boolean>>(
	{},
).pipe(Atom.keepAlive);

const EMPTY_BUNDLES: ProjectBundle[] = [];

/** Per-connection bundles; notifies only when this connection's change. */
export const connectionBundlesAtom = Atom.family((connKey: string) =>
	Atom.make((get) => get(bundlesByConnectionAtom)[connKey] ?? EMPTY_BUNDLES),
);
/** Per-session status; notifies only when this session's status changes. */
export const sessionStatusAtom = Atom.family((sessionKey: string) =>
	Atom.make((get) => get(statusBySessionAtom)[sessionKey]),
);
export const connectionSessionsErrorAtom = Atom.family((connKey: string) =>
	Atom.make((get) => get(errorByConnectionAtom)[connKey] ?? null),
);
export const connectionSessionsLoadingAtom = Atom.family((connKey: string) =>
	Atom.make((get) => get(loadingByConnectionAtom)[connKey] === true),
);

const chatFibers = new Map<string, Fiber.Fiber<unknown, unknown>>();
const sessionSummaryFibers = new Map<string, Fiber.Fiber<unknown, unknown>>();

const stopFiber = async (
	key: string,
	map: Map<string, Fiber.Fiber<unknown, unknown>>,
) => {
	const fiber = map.get(key);
	if (fiber !== undefined) {
		map.delete(key);
		await Effect.runPromise(Fiber.interrupt(fiber)).catch(() => {});
	}
};

export const resetSessionsRuntime = async (): Promise<void> => {
	sessionRefreshCoordinator.reset();
	await Promise.all([
		...Array.from(chatFibers.keys(), (key) => stopFiber(key, chatFibers)),
		...Array.from(sessionSummaryFibers.keys(), (key) =>
			stopFiber(key, sessionSummaryFibers),
		),
	]);
	batchAtomUpdates(() => {
		appAtomRegistry.set(bundlesByConnectionAtom, {});
		appAtomRegistry.set(statusBySessionAtom, {});
		appAtomRegistry.set(errorByConnectionAtom, {});
		appAtomRegistry.set(loadingByConnectionAtom, {});
	});
};

const currentBundles = (connKey: string): ProjectBundle[] =>
	appAtomRegistry.get(bundlesByConnectionAtom)[connKey] ?? [];

const setConnectionBundles = (
	connKey: string,
	bundles: ProjectBundle[],
): void => {
	appAtomRegistry.update(bundlesByConnectionAtom, (state) => ({
		...state,
		[connKey]: bundles,
	}));
};

const setConnectionError = (connKey: string, error: string | null): void => {
	appAtomRegistry.update(errorByConnectionAtom, (state) => ({
		...state,
		[connKey]: error,
	}));
};

const setConnectionLoading = (connKey: string, loading: boolean): void => {
	appAtomRegistry.update(loadingByConnectionAtom, (state) => ({
		...state,
		[connKey]: loading,
	}));
};

type SnapshotStreamSupervisorOptions = {
	readonly connectionKey: string;
	readonly connectionOptions: WsProtocolOptions;
	readonly isReady: () => boolean;
	readonly failReady: (cause: unknown) => void;
	readonly completedMessage: string;
	readonly missingSnapshotMessage: string;
};

const superviseSnapshotStream = <E, R>(
	program: Effect.Effect<void, E, R>,
	options: SnapshotStreamSupervisorOptions,
): Effect.Effect<void, never, R> =>
	program.pipe(
		Effect.tap(() =>
			Effect.sync(() => {
				if (!options.isReady()) return;
				const cause = new Error(options.completedMessage);
				retryConnectionNow(options.connectionOptions);
				setConnectionError(options.connectionKey, cause.message);
			}),
		),
		Effect.catch((cause) =>
			Effect.sync(() => {
				if (!options.isReady()) {
					options.failReady(cause);
					return;
				}
				reportConnectionFailure(options.connectionOptions, cause);
				setConnectionError(
					options.connectionKey,
					connectionErrorMessage(cause),
				);
			}),
		),
		Effect.ensuring(
			Effect.sync(() => {
				if (!options.isReady()) {
					options.failReady(new Error(options.missingSnapshotMessage));
				}
			}),
		),
	);

export const archiveChat = async (
	connKey: string,
	options: WsProtocolOptions,
	chatId: Chat["id"],
): Promise<void> => {
	const previous = currentBundles(connKey);
	setConnectionBundles(connKey, removeChat(previous, chatId));
	try {
		const client = await Effect.runPromise(getConnectionClient(options));
		await Effect.runPromise(client["chat.archive"]({ chatId }));
	} catch (cause) {
		reportConnectionFailure(options, cause);
		batchAtomUpdates(() => {
			setConnectionBundles(connKey, previous);
			setConnectionError(connKey, connectionErrorMessage(cause));
		});
	}
};

export const archiveSession = async (
	connKey: string,
	options: WsProtocolOptions,
	sessionId: Session["id"],
): Promise<void> => {
	const previous = currentBundles(connKey);
	setConnectionBundles(connKey, removeSession(previous, sessionId));
	try {
		const client = await Effect.runPromise(getConnectionClient(options));
		await Effect.runPromise(client["session.archive"]({ sessionId }));
	} catch (cause) {
		reportConnectionFailure(options, cause);
		batchAtomUpdates(() => {
			setConnectionBundles(connKey, previous);
			setConnectionError(connKey, connectionErrorMessage(cause));
		});
	}
};

export const renameChat = async (
	connKey: string,
	options: WsProtocolOptions,
	chatId: Chat["id"],
	title: string,
): Promise<void> => {
	const trimmed = title.trim();
	if (trimmed.length === 0) return;
	const previous = currentBundles(connKey);
	setConnectionBundles(
		connKey,
		patchChatFields(previous, chatId, { title: trimmed }),
	);
	try {
		const renamed = await Effect.runPromise(
			renameChatRpc({ connection: options, chatId, title: trimmed }),
		);
		setConnectionBundles(connKey, patchChat(currentBundles(connKey), renamed));
	} catch (cause) {
		reportConnectionFailure(options, cause);
		batchAtomUpdates(() => {
			setConnectionBundles(connKey, previous);
			setConnectionError(connKey, connectionErrorMessage(cause));
		});
		throw cause;
	}
};

