						Archive
					</Text>
				</Pressable>
			)}
		>
			{content}
		</Swipeable>
	);
}, areChatRowPropsEqual);

function areChatRowPropsEqual(
	previous: HomeChatRowProps,
	next: HomeChatRowProps,
): boolean {
	return (
		previous.item.row === next.item.row &&
		previous.item.context === next.item.context &&
		previous.item.showProject === next.item.showProject &&
		previous.item.isFirst === next.item.isFirst &&
		previous.item.isLast === next.item.isLast &&
		previous.onArchive === next.onArchive &&
		previous.onTogglePin === next.onTogglePin
	);
}

