				status: member.status,
				projectAvailable: true,
				setupAvailable: false,
				retryable: member.status === "error" || member.status === "offline",
				selected:
					resolved !== null &&
					member.environmentId === resolved.environmentId &&
					member.folderId === resolved.folderId,
