								accessibilityRole="button"
								accessibilityLabel={row.pinned ? "Unpin chat" : "Pin chat"}
								className="w-24 items-center justify-center bg-muted"
								onPress={() => {
									methods.close();
									onTogglePin(item);
								}}
							>
								<HugeIcon
									icon={row.pinned ? PinOffIcon : PinIcon}
									size={20}
									color={colors.secondaryFg}
								/>
								<Text className="mt-1 font-sans-medium text-[12px] text-muted-foreground">
									{row.pinned ? "Unpin" : "Pin"}
								</Text>
							</Pressable>
						)
					: undefined
			}
			renderRightActions={(_, __, methods) => (
				<Pressable
					accessibilityRole="button"
					accessibilityLabel="Archive chat"
					className="w-24 items-center justify-center bg-danger/15"
					onPress={() => {
						methods.close();
						void onArchive(item);
					}}
				>
					<HugeIcon icon={ArchiveIcon} size={20} color={colors.danger} />
					<Text className="mt-1 font-sans-medium text-[12px] text-danger">
						Archive
					</Text>
				</Pressable>
			)}
		>
			{content}
		</Swipeable>
	);
}, areChatRowPropsEqual);

function areChatRowPropsEqual(
	previous: HomeChatRowProps,
	next: HomeChatRowProps,
): boolean {
	return (
		previous.item.row === next.item.row &&
		previous.item.context === next.item.context &&
		previous.item.showProject === next.item.showProject &&
		previous.item.isFirst === next.item.isFirst &&
		previous.item.isLast === next.item.isLast &&
		previous.onArchive === next.onArchive &&
		previous.onTogglePin === next.onTogglePin
	);
}

